#define GENERATE_VAR(name, suffix) name##_##suffix

// Concatenating identifiers
int GENERATE_VAR(my_data, count) = 10;
// Expands to: int my_data_count = 10;

// Creating method names
#define DECLARE_METHOD(Type) void get##Type()

DECLARE_METHOD(Value);
// Expands to: void getValue();

